@push('scripts')<script>
(()=>{const box=document.getElementById('wmsErrorAlert'),title=box?.querySelector('[data-wms-error-title]'),message=box?.querySelector('[data-wms-error-message]');const showError=e=>{if(!box)return;title.textContent=e?.title||'خطای سرویس نقشه';message.textContent=e?.message||'در ارتباط با سرویس نقشه مشکلی رخ داد. لطفاً دوباره تلاش کنید.';box.classList.remove('d-none');};box?.querySelector('[data-wms-error-close]')?.addEventListener('click',()=>box.classList.add('d-none'));document.querySelector('[data-wms-test]')?.addEventListener('click',async e=>{const button=e.currentTarget,form=button.closest('form'),result=form.querySelector('[data-wms-result]');if(button.disabled)return;button.disabled=true;result.textContent='در حال بررسی…';box?.classList.add('d-none');try{const response=await fetch('{{ route('settings.gis.wms.test') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:new URLSearchParams(Object.fromEntries(new FormData(form)))});const json=await response.json();if(!response.ok||json.success===false){showError(json.error);result.textContent='';return;}result.textContent=`نسخه ${json.version}، ${json.layers.length} لایه`;}catch(_){showError({title:'ارتباط با سرور WMS برقرار نشد',message:'سرور نقشه پاسخ نمی‌دهد. اتصال شبکه و وضعیت سرویس را بررسی کنید.'});result.textContent='';}finally{button.disabled=false;}});})();
</script>@endpush
